7	/**
8	 * Flags a soft duplicate at creation time. A hard duplicate (same {@link OwnerIdentity identity
9	 * key}) has already been rejected by {@link EnsureUniqueIdentity}, so any collision here is a
10	 * softer one: an existing owner that shares this owner's last name (case-insensitively) and
11	 * postcode but has a different telephone. Such an owner is still created, but flagged
12	 * {@code possibleDuplicate = true} with {@code possibleDuplicateOf} set to the matching owner's
13	 * id; otherwise {@code possibleDuplicate = false}.
14	 *
15	 * <p>Runs after {@link BuildOwner} has produced the entity and before {@link SaveOwner} persists
16	 * it, so {@code findAll()} sees only the owners that existed before this create. The flags are
17	 * stored on the owner and returned on every later read.
18	 */
19	public class FlagPossibleDuplicate {
20	
21	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
22	        owner.setPossibleDuplicate(false);
23	        owner.setPossibleDuplicateOf(null);
24	
25	        String postcode = owner.getPostcode();
26	        if (owner.getLastName() == null || postcode == null || postcode.isBlank()) {
27	            return;
28	        }
29	        String telephone = TelephoneNormalizer.toE164(owner.getTelephone());
30	        for (Owner existing : ownerRepository.findAll()) {
31	            if (owner.getLastName().equalsIgnoreCase(existing.getLastName())
32	                    && postcode.equals(existing.getPostcode())
33	                    && !equalsIgnoreNull(telephone, TelephoneNormalizer.toE164(existing.getTelephone()))) {
34	                owner.setPossibleDuplicate(true);
35	                owner.setPossibleDuplicateOf(existing.getId());
36	                return;
37	            }
38	        }
39	    }
40	
41	    private static boolean equalsIgnoreNull(String a, String b) {
42	        return a == null ? b == null : a.equals(b);
43	    }
44	}
