3	import java.util.Locale;
4	
5	import org.springframework.samples.petclinic.util.Sha256;
6	
7	/**
8	 * Canonical key identifying a household by its owner's last name and address. Two owners
9	 * belong to the same household when their keys are equal: last name and address are compared
10	 * case-insensitively with leading/trailing and repeated whitespace collapsed to a single
11	 * space, so incidental formatting differences do not hide a match.
12	 */
13	final class HouseholdKey {
14	
15	    private HouseholdKey() {
16	    }
17	
18	    static String of(String lastName, String address) {
19	        return normalize(lastName) + '�' + normalize(address);
20	    }
21	
22	    /**
23	     * Stable identifier shared by every owner of a household: the SHA-256 hex digest of the
24	     * canonical {@link #of(String, String) key}. Purely derived from last name and address, so
25	     * two owners in the same household always get the same value regardless of creation order.
26	     */
27	    static String id(String lastName, String address) {
28	        return Sha256.hex(of(lastName, address));
29	    }
30	
31	    private static String normalize(String value) {
32	        if (value == null) {
33	            return "";
34	        }
35	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
36	    }
37	}
