3	/**
4	 * Thrown when a create-owner request derives an identity key that is already used by another
5	 * owner. The key consolidates telephone, email and household, so this is the single duplicate
6	 * signal for owner creation. Handled by {@link DuplicateIdentityExceptionHandler}, which
7	 * responds 409 with the conflicting key.
8	 */
9	public class DuplicateIdentityException extends Exception {
10	
11	    private final String identityKey;
12	
13	    public DuplicateIdentityException(String identityKey) {
14	        super("Owner identity is already used by another owner: " + identityKey);
15	        this.identityKey = identityKey;
16	    }
17	
18	    public String getIdentityKey() {
19	        return this.identityKey;
20	    }
21	}
