40	    /** Upper-cased first letters of first and last name, dot-separated with a trailing dot (e.g. 'J.S.'). */
41	    default String initials(Owner owner) {
42	        return initial(owner.getFirstName()) + initial(owner.getLastName());
43	    }
44	
45	    private static String initial(String name) {
46	        return Character.toUpperCase(name.charAt(0)) + ".";
47	    }
48	
49	    /**
50	     * Derive the membership number '&lt;customerCode&gt;-M&lt;YY&gt;', where YY is the last
51	     * two digits of the registration date year (e.g. 'SYD-SMI-0007-M26'). Returns null when
52	     * either source field is absent.
53	     */
54	    default String membershipNumber(Owner owner) {
55	        if (owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
