92	     * when no birth date was supplied.
93	     */
94	    default OwnerDto.AgeBandEnum ageBand(Owner owner) {
95	        AgeBand band = AgeBand.of(owner.getBirthDate(), owner.getRegistrationDate());
96	        return band == null ? null : OwnerDto.AgeBandEnum.valueOf(band.name());
97	    }
