package org.springframework.samples.petclinic.acceptance;

import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;
import tools.jackson.databind.node.ObjectNode;

class TmpHouseholdBlockTest extends AcceptanceBase {

    @Test
    void secondSameHouseholdWithoutSharesIsRejected409() throws Exception {
        String lastName = uniqueLastName();
        ObjectNode a = ownerNode();
        a.put("lastName", lastName);
        a.put("postcode", "2000");
        createOwnerOk(a);

        ObjectNode b = ownerNode();
        b.put("lastName", lastName);
        b.put("postcode", "2000");
        // no sharesHousehold -> household duplicate
        createOwner(b).andExpect(status().isConflict());
    }

    @Test
    void declaredMemberIsNotFlaggedPossibleDuplicate() throws Exception {
        String lastName = uniqueLastName();
        ObjectNode a = ownerNode();
        a.put("lastName", lastName);
        a.put("postcode", "2000");
        createOwnerOk(a);

        ObjectNode b = ownerNode();
        b.put("lastName", lastName);
        b.put("postcode", "2000");
        b.put("sharesHousehold", true);
        int id = createOwnerOk(b);
        assertEquals(false, fetchOwner(id).get("possibleDuplicate").asBoolean());
    }
}
